    "statement": "A educação grega sempre procurou cultivar o espírito \ncívico, o orgulho de pertencer a uma cidade livre, a lealdade \nà comunidade política. Primeiramente, a ênfase recaía sobre o treinamento militar. Entretanto, desde o século VI a.C., \nprimeiro em Atenas, depois no resto da Grécia — exce\ntuando-se sempre Esparta —, as preocupações militares \nvinham em segundo lugar. Todavia, educação significava \nainda principalmente educação física; para os gregos, estava em primeiro lugar — e assim foi durante longo tempo — a \npalestra1 e o ginásio, onde a criança e o adolescente eram \ntreinados nos esportes. A educação grega não só era mais \nfísica que intelectual; era também artística, especificamente \nmusical, antes de ser literária.\n\n(H. -I. Marrou. “Educação e retórica”. In: Moses Finley (org.). O legado da\n\nGrécia: uma nova avaliação, 1998. Adaptado.)\n\n1 Palestra: do grego palaistra — local para exercícios corporais.\n\nDe acordo com o excerto, na pólis grega, a educação a partir \ndo século VI a.C.",
