    "statement": "Embora a escravidão já existisse na África Ocidental antes da chegada dos europeus, ela assumiu outro significado. \nDoravante, o cativo tornou-se uma “peça”, termo que evoca \npor si mesmo sua condição de mercadoria, cujo valor podia \noscilar de acordo com a lei da oferta e da procura. Essa escravidão em massa, por sua vez, inundou a Europa, e depois \ntoda a América, com uma categoria social completamente privada de direitos que passava a constituir a base de toda a exploração econômica, motivo pelo qual certos pesquisadores \nidentificam a existência de organizações sociais escravistas \nespecíficas na Era Moderna.\n\n(José Rivair Macedo. História da África, 2015.)\n\nO excerto apresenta alguns aspectos das “organizações sociais escravistas” do século XV ao XIX. Um desses aspectos \napresentados refere-se",
