    "statement": "No Brasil, a migração indígena para os centros urbanos \ntem se intensificado nos últimos 30 anos implicando tanto desafios particulares para preservar a identidade étnica como a \nfalta de emprego, de acesso à saúde, à educação, à moradia \nadequada e a outros direitos fundamentais. A vulnerabilidade \nde povos, famílias ou pessoas indígenas é reconhecida no \nRelatório da Organização das Nações Unidas sobre a Promoção e a Proteção dos Direitos Humanos de Migrantes no \nContexto de Grandes Movimentos. A migração de indígenas \npara as cidades, voluntária ou forçada, em geral decorre da \nviolação dos direitos, como nos casos em que é motivada \npela expulsão dos territórios de origem, insegurança econômica, ausência ou precariedade de serviços básicos.\n\n(Mariana W. V. de Castilho e Ela W. V de Castilho.\n\nConfluências, dezembro de 2023. Adaptado.)\n\nCaracteriza uma consequência da realidade indígena retratada no excerto:",
