    "statement": "O crescimento desordenado de Manaus, em um processo histórico, privilegiou o transporte de rodas motorizado em \ndetrimento de outros modais, como o hidroviário. Para Marcos Castro, professor da Universidade Federal do Amazonas \n(UFAM), mesmo sendo cortada por igarapés e cercada por \nrios, a cidade nunca teve propostas concretas sobre o transporte coletivo urbano hidroviário. Segundo Castro, essa seria \numa das soluções para desconcentrar a operação do transporte rodoviário. O professor completa, ainda, que a interligação das zonas ocorreria por meio de portos em toda a orla \nde Manaus. Nos bairros, a possibilidade seria a instalação de \nhidrovias urbanas nos igarapés.\n\n(Marcelo Moreira. https://amazonasatual.com.br, 08.09.2023. Adaptado.)\n\nSão fatores que limitam a implantação do modal hidroviário \nem Manaus:",
