    "difficulty": "Difícil",
    "statement": "Leia o trecho do romance Ciranda de pedra, de Lygia Fagundes Telles, para responder às questões de 26 a 30.\n\nVirgínia subiu precipitadamente a escada e trancou-se \nno quarto.\n\n— Abre, menina — ordenou Luciana do lado de fora.\nVirgínia encostou-se à parede e pôs-se a roer as unhas, \nseguindo com o olhar uma formiguinha que subia pelo batente da porta. “Se entrar aí nessa fresta, você morre!”, sussurrou soprando-a para o chão. “Eu te salvo, bobinha, não tenha \nmedo”, disse em voz alta. E afastou-a com o indicador. Nesse \ninstante fixou o olhar na unha roída até a carne. Pensou nas \nunhas de Otávia. E esmagou a formiga.\n\n— Virgínia, eu não estou brincando, menina. Abre \nlogo, anda!\n\n— Agora não posso.\n— Não pode por quê?\n— Estou fazendo uma coisa — respondeu evasivamente.\nPensava em Conrado a lhe explicar que os bichos são \ncomo gente, têm alma de gente, e que matar um bichinho era \no mesmo que matar uma pessoa. “Se você for má e começar \na matar só por gosto, na outra vida você será bicho também, \nmas um desses bichos horríveis, cobra, rato, aranha...” Deitou-se no assoalho e começou a se espojar angustiosamente, avançando de rastros até o meio do quarto.\n\n— Ou você abre ou conto para o seu tio. É isto que você \nquer, é isto?\n\nVirgínia imobilizou-se. Ser cobra machucava os cotovelos, \nmelhor ser borboleta. Mas quem ia ser borboleta decerto era \nOtávia, que era linda. “E eu sou feia e ruim, ruim, ruim!”, exclamou dando murros no chão. Ergueu a cabeça num desafio:\n\n— Pode contar tudo, tio Daniel não me manda, quem \nmanda em mim é meu pai, ouviu? Meu pai.\n\n(Ciranda de pedra, 2009.)\n\nDe acordo com a cena narrada, a personagem Virgínia, quando criança, era:",
