    "statement": "Considere o texto “Serial lover”, escrito por Carpinejar, para \nresponder às questões de 32 a 35.\n\nExiste uma infidelidade mais secreta e menos evidente, \nque acontece depois do relacionamento. Só acontece depois. \nÉ uma traição póstuma, retardatária, residual.\n\nÉ quando você repete os mesmos lugares, os mesmos \napelos, as mesmas confidências com outro. É quando você \ninsiste em escrever e tecer declarações exatamente iguais.\n\nÉ uma extorsão sentimental colocar um desejo para sua \nnova companhia como se fosse inédito.\n\nPois a paixão só é idêntica para quem não enxerga \nas diferenças.\n\nÉ como remanejar presentes, aproveitar alianças antigas.\nVocê prova que não tem criatividade nenhuma, demonstra a maior apatia: refaz os passeios que já realizou, leva para \nos restaurantes que frequentava, as baladas e festas conhecidas, reincide nos roteiros de viagem, destina sonhos e palavras já gastos, reemprega até os nomes aprovados para \nquando nascessem seus filhos.\n\nMudou a pessoa, mas não o seu jeito de seduzir. Mudou \na pessoa, mas não sua rotina de amar. Mudou a pessoa, mas \nnão seu script.\n\nÉ uma melancólica sobreposição, desastrada colagem.\nNem precisa cometer o ato falho de trocar o nome do atual pelo ex, porque estará revisitando atmosferas e cenários. \nExperimenta locações contaminadas por juras velhas.\n\nNão há sensação mais ingrata para seu namorado anterior ao perceber que era mais um. Um qualquer, nem um \npouco especial. Um sósia de cenas românticas. Um dublê da \nadrenalina e dos feromônios.\n\nVocê oferece um passado usado sob o disfarce de futuro. \nAlcança aquilo que foi ensaiado com o antecessor. Não se dá \no luxo de disfarçar, o trabalho de maquiar, colocar uma manta \nno mobiliário da memória.\n\nRecorrendo à fórmula fixa de história feliz, estabelece \numa competição imaginária, anula a individualidade do seu \npar, apaga a invenção a dois e a costura por caminhos surpreendentes e inesquecíveis.\n\nAcredita em sua inocência porque ninguém comentará \no assunto. Desfruta da tolerância dos garçons, dos colegas, \ndos amigos, dos parentes. É realmente um segredo com pequenas chances de ser revelado, porém a consciência não é \nboba e um dia se vinga.\n\nO que vive está longe de ser amor, é obsessão.\n\n(Carpinejar. Para onde vai o amor, 2015.)\n\nOcorre uma palavra formada com um prefixo que expressa \nnegação em:",
